'use strict';
// Voice packs (语音包): her fixed lines recorded ahead, played straight from disk — no key, no network,
// no per-minute limit (MiniMax allows 10 a minute). Agent replies are not fixed and still go to an engine.
//
// A pack is a folder: manifest.json + audio files.
//   { "format": 1, "id": "dafeiyu-minimax", "name": "…", "character": "dafeiyu",
//     "engine": "minimax", "voiceId": "qiaopi_mengmei", "model": "speech-2.8-turbo", "credit": "…",
//     "lines": { "<line as read>": "<file>.mp3", … } }
// Built-in packs live in src/voicepacks/<id>/ (generated by scripts/voicepack-generate.js); packs the
// owner adds go in userData/voicepacks/<id>/ and win over a built-in one for the same character.
// A line is looked up exactly as it is sent to an engine (speakable text, one sentence or a whole short line).

const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const Voice = require('./voice');
const dialogue = require('./dialogue');
const touchZones = require('./touch-zones');

const FORMAT = 1;
const MIME = { mp3: 'audio/mpeg', wav: 'audio/wav', ogg: 'audio/ogg', opus: 'audio/opus' };
// what main.js does to a line before it reaches an engine (core/tts.js synthesize)
const norm = (text) => String(text || '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim();
const fileFor = (text) => `${crypto.createHash('sha1').update(norm(text)).digest('hex').slice(0, 16)}.mp3`;

// Lines the app itself says outside the character files (pet-service.js).
const APP_LINES = ['呃……肚子圆滚滚的，吃不下了。', '好累……让我睡一会儿。', '哈——睡饱啦。'];
// Parts of a character file that are never read aloud.
const SKIP_KEYS = new Set(['id', 'order', 'vendor', 'model', 'models', 'name', 'nameZh', 'title', 'accent', 'blurb', 'personality', 'likes', 'art', 'fx', 'credits', 'signature', 'outfits', 'memes', 'adult', 'tts', 'lang', 'prefer', 'zones', 'videoBox', 'poses']);

const strings = (o, out = []) => {
  if (typeof o === 'string') { if (/[㐀-鿿]/.test(o)) out.push(o); }
  else if (Array.isArray(o)) o.forEach((x) => strings(x, out));
  else if (o && typeof o === 'object') for (const [k, v] of Object.entries(o)) if (!SKIP_KEYS.has(k)) strings(v, out);
  return out;
};

// Every fixed line she may say, as it is sent to an engine: the whole line (interaction lines and murmurs
// are read whole) and each sentence of it (replies and milestones are read sentence by sentence).
function packLines(species) {
  const raw = [
    ...strings(species),
    ...strings(dialogue.STAGE_LINES),
    ...strings(touchZones.DEFAULT_LINES),
    ...strings(touchZones.ADULT_LINES),
    ...APP_LINES,
  ];
  const out = new Set();
  for (const line of raw) {
    const whole = norm(Voice.speakable(line));
    if (whole) out.add(whole);
    for (const p of Voice.sentences(line)) if (p.say) out.add(norm(p.say));
  }
  return [...out];
}

// Problems with a manifest (empty = valid). `dir` checks that every file is there.
function validateManifest(m, dir = null) {
  const errors = [];
  if (!m || typeof m !== 'object') return ['manifest.json must be an object'];
  if (m.format !== FORMAT) errors.push(`format must be ${FORMAT}`);
  for (const k of ['id', 'name', 'character']) if (typeof m[k] !== 'string' || !m[k].trim()) errors.push(`${k} is required`);
  if (m.id && !/^[a-z0-9][a-z0-9-]{0,63}$/.test(m.id)) errors.push('id: lowercase letters, digits and -');
  if (!m.lines || typeof m.lines !== 'object' || Array.isArray(m.lines)) errors.push('lines must map each line to its audio file');
  else for (const [text, file] of Object.entries(m.lines)) {
    if (!norm(text) || typeof file !== 'string' || !/^[\w.-]+\.(mp3|wav|ogg|opus)$/.test(file) || file.includes('..')) { errors.push(`lines: bad entry for "${text.slice(0, 20)}"`); break; }
    if (dir && !fs.existsSync(path.join(dir, file))) { errors.push(`lines: missing file ${file}`); break; }
  }
  return errors;
}

class VoicePacks {
  // dirs: folders that hold one pack per subfolder, later ones winning (built-in first, the owner's last)
  constructor(dirs = [], { log = () => {} } = {}) {
    this.dirs = dirs;
    this.log = log;
    this.reload();
  }

  reload() {
    this.byCharacter = {}; // character -> pack
    this.errors = [];
    for (const root of this.dirs) {
      let names = [];
      try { names = fs.readdirSync(root, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name); } catch { continue; }
      for (const name of names.sort()) {
        const dir = path.join(root, name);
        try {
          const m = JSON.parse(fs.readFileSync(path.join(dir, 'manifest.json'), 'utf8'));
          const errors = validateManifest(m, dir);
          if (errors.length) { this.errors.push({ dir, errors }); this.log(new Error(`voice pack ${dir}: ${errors.join('; ')}`)); continue; }
          const lines = new Map(Object.entries(m.lines).map(([t, f]) => [norm(t), f]));
          this.byCharacter[m.character] = { ...m, dir, lines, builtIn: root === this.dirs[0] };
        } catch (e) {
          this.errors.push({ dir, errors: [e.message] });
        }
      }
    }
  }

  packFor(characterId) {
    return this.byCharacter[characterId] || null;
  }

  list() {
    return Object.values(this.byCharacter).map((p) => ({ id: p.id, name: p.name, character: p.character, engine: p.engine || null, voiceId: p.voiceId || null, credit: p.credit || '', lines: p.lines.size, builtIn: p.builtIn }));
  }

  // The recorded line, or null. { audio, mime, provider: 'pack', packId, engine, voiceId }
  lookup(characterId, text) {
    const p = this.packFor(characterId);
    const file = p && p.lines.get(norm(text));
    if (!file) return null;
    try {
      const audio = fs.readFileSync(path.join(p.dir, file));
      return { audio, mime: MIME[path.extname(file).slice(1)] || 'audio/mpeg', provider: 'pack', packId: p.id, engine: p.engine || null, voiceId: p.voiceId || null };
    } catch {
      return null;
    }
  }
}

// Whether a recorded line should be played instead of asking an engine: packs on, and the engine that
// would read this line is the one the pack was recorded with — or there is no engine she could use at
// all (a recorded line beats the system voice). With 系统语音 chosen, never.
function packApplies(tts, pack, firstEngine) {
  if (!pack || !tts || tts.packs === false || tts.provider === 'system') return false;
  return !firstEngine || !pack.engine || firstEngine === pack.engine;
}

module.exports = { FORMAT, APP_LINES, norm, fileFor, packLines, validateManifest, VoicePacks, packApplies };
